import {checkinHTML} from './checkin.mjs';
import {fingerprint,analyzeText,recordsForPerson,applyReview,nameKey,needsReading,syncDetectedParticipants,extractPurchase,journeysForPerson,syncJourneys} from './document-model.mjs';
import {extractDocument,supportedFile,releaseOCR,documentFormat} from './document-reader.mjs';
export function createDocumentFeatures(ctx){const {esc,field,select,modal,toast,read,persist,render,getTrip,getState,localFile}=ctx;let job=null;let reviewRows=[],reviewPath='',reviewTripId='';const el=s=>document.querySelector(s);const reading=(t,path)=>t.readings?.[path];const pending=t=>t.files.filter(f=>{const r=reading(t,f.path);return r&&r.reviewedFingerprint!==r.fingerprint&&r.status!=='ignored'}).length;
function panel(t){return `<section class="reader-panel"><div><h3>Leer y asociar documentos</h3><p>Detecta pasajeros y trayectos en PDF, Excel, CSV e imágenes. Los documentos se asocian a los participantes del viaje. Los nombres que no coinciden quedan pendientes de revisión y no crean personas nuevas.</p><span class="small muted">${pending(t)} documentos por revisar · Lectura en tu ordenador</span></div><div class="actions"><button class="button" data-action="analyze-documents" ${job?'disabled':''}>Leer documentos</button>${pending(t)?"<button class=\"button secondary\" data-action=\"review-next\">Revisar propuestas</button>":''}</div><div id="readingProgress" class="reading-progress" role="status" aria-live="polite">${job?.tripId===t.id?progressHTML():''}</div></section>`}
function progressHTML(){return `<span>${esc(job.message||"Preparando lectura…")}</span><progress value="${job.done}" max="${job.total||1}"></progress><button class="text-button" data-action="stop-reading">Detener lectura</button>`}
function updateProgress(message){if(!job)return;job.message=message;const node=el('#readingProgress');if(node&&getTrip()?.id===job.tripId)node.innerHTML=progressHTML()}
function status(t,f){const r=reading(t,f.path);if(!r||r.status==='unread')return "<span class=\"status neutral\">Sin leer</span>";if(r.fingerprint!==fingerprint(f))return "<span class=\"status\">Documento modificado</span>";if(r.status==='error')return '<span class="status">Lectura no completada</span>';if(r.status==='unsupported')return "<span class=\"status neutral\">Asociación manual</span>";if(r.status==='ignored')return '<span class="status neutral">Omesa</span>';if(r.reviewedFingerprint===r.fingerprint){const names=(r.confirmed||[]).map(c=>t.people.find(p=>p.id===c.personId)?.name).filter(Boolean);return `<span class="status done">Asociado</span><small>${names.map(esc).join(', ')}</small>`}return `<span class="status">${r.proposals?.length||0} coincidencias · Revisar</span>`}
async function analyze(t=getTrip(),path){if(t?.rosterMode==='excel'&&!t.people.length){toast("Añade primero los participantes.");return}if(job){toast("Ya hay una lectura en curso.");return}if(!t?.files.length){toast("Vincula una carpeta con documentos.");return}const requested=t.files.filter(f=>path?f.path===path:needsReading(f,t.readings?.[f.path]));const files=requested.slice(0,100);const cached=syncDetectedParticipants(t);if(cached.added||cached.linked||cached.updated)await persist();if(!files.length){toast(cached.added?`${cached.added} participantes creats a partir dels documentos llegits.`:t.people.length?"Lista de participantes actualizada. Revisa los trayectos detectados.":"No se han detectado nombres de pasajeros. Abre «Revisar / asociar» para ver el texto leído.");ctx.goToParticipants();return}job={tripId:t.id,added:cached.added,done:0,total:files.length,message:"Preparando lectura…",controller:new AbortController()};ctx.goToDocuments();try{const saved=await read('folders',t.id);if(!saved)throw Error("Vuelve a vincular la carpeta para poder leerla.");if(saved.handle&&await saved.handle.requestPermission({mode:'read'})!=='granted')throw Error('Cal donar permís de lectura a la carpeta.');t.readings??={};for(const meta of files){if(job.controller.signal.aborted)break;const old=t.readings[meta.path];updateProgress(`${job.done+1}/${files.length} · ${meta.name}`);let result;try{let file;if(saved.handle){let dir=saved.handle;const parts=meta.path.split('/');for(const part of parts.slice(0,-1))dir=await dir.getDirectoryHandle(part);file=await(await dir.getFileHandle(parts.at(-1))).getFile()}else{file=saved.files?.find(f=>f.path===meta.path)?.file;if(!file)throw Error('Document no disponible. Actualitza la carpeta.');}if(!supportedFile(meta.name)&&await documentFormat(file)!=='pdf'){result={status:'unsupported',text:'',proposals:[],warnings:["Formato no compatible. Puedes asociar este documento manualmente."]}}else{const content=await extractDocument(file,{signal:job.controller.signal,progress:message=>updateProgress(`${job.done+1}/${files.length} · ${meta.name} · ${message}`)});const parsed=t.rosterMode==='excel'&&meta.name===t.rosterSource?{text:content.text,proposals:[],warnings:["Lista oficial de participantes. Las reservas se asocian desde los demás documentos."]}:analyzeText({...content,people:t.people,name:meta.name});result={...parsed,warnings:[...content.warnings,...parsed.warnings],method:content.method,status:'ready'}}}catch(e){if(e.name==='AbortError')break;result={status:'error',text:'',proposals:[],warnings:[e.message||"No se ha podido leer este documento."]}}t.readings[meta.path]={...result,name:meta.name,fingerprint:fingerprint(meta),readAt:Date.now(),confirmed:old?.confirmed||[],reviewedAt:old?.reviewedAt||null,reviewedFingerprint:old?.reviewedFingerprint||null,dismissedNames:old?.dismissedNames||[]};const synced=syncDetectedParticipants(t);job.added+=synced.added;job.done++;await persist();}toast(job.controller.signal.aborted?"Lectura detenida. Se han guardado las propuestas ya leídas.":`${job.done} documentos llegits · ${job.added} participantes nous · ${t.people.length} participantes al viaje. Revisa els trayectos.${requested.length>100?" Pulsa «Leer documentos» para continuar con el resto.":''}`)}finally{await releaseOCR().catch(()=>{});job=null;if(getTrip()?.id===t.id&&t.people.length)ctx.goToParticipants();else render()}}
function rowHTML(row,i,t){return `<section class="association-row" data-row="${i}"><div class="association-head"><label class="check-label"><input type="checkbox" name="enabled_${i}" ${row.enabled?'checked':''}> Asociar esta persona</label><button type="button" class="text-button error" data-action="remove-association" data-id="${i}">Quitar</button></div><div class="form-grid">${select("Participante",'person_'+i,row.personId||'',[['',t.rosterMode==='excel'?"Selecciona un participante del viaje":"Crear participante / nombre detectado"],...t.people.map(p=>[p.id,p.name])])}${field("Nombre detectado o participante nuevo",'newname_'+i,row.name||'')}</div><fieldset class="purchase-fields"><legend>Datos de compra</legend><div class="form-grid">${field("Referencia de compra",`purchaseReference_${i}`,row.purchase?.reference||'')}${field('Email de compra',`purchaseEmail_${i}`,row.purchase?.email||'','email')}</div></fieldset>${row.unmatched?"<div class=\"notice\">Este nombre no coincide con la lista de participantes. Selecciona la persona correcta o déjalo sin asociar.</div>":''}${row.nameVariant?"<div class=\"notice\">El nombre de este documento tiene una variante o menos apellidos. Comprueba la asociación propuesta.</div>":''}${row.evidence?`<p class="evidence"><strong>Texto del documento:</strong> ${esc(row.evidence)}</p>`:''}<div class="journey-editor">${row.segments.map((s,j)=>`<fieldset><legend>Trayecto ${j+1}</legend><div class="form-grid">${field('Origen',`origin_${i}_${j}`,s.origin)}${field("Destino",`destination_${i}_${j}`,s.destination)}${field("Salida · fecha y hora",`departure_${i}_${j}`,s.departure)}${field("Llegada · fecha y hora",`arrival_${i}_${j}`,s.arrival)}${field("Vuelo / tren / vehículo",`service_${i}_${j}`,s.service)}${field("Localizador",`reference_${i}_${j}`,s.reference)}</div><button type="button" class="text-button error" data-action="remove-segment" data-id="${i}:${j}">Quitar trajecte</button></fieldset>`).join('')}</div><button type="button" class="text-button" data-action="add-segment" data-id="${i}">＋ Añadir trajecte</button></section>`}
function collect(){const form=el('#modalForm'),data=new FormData(form);reviewRows=reviewRows.map((r,i)=>({...r,enabled:data.has('enabled_'+i),personId:data.get('person_'+i)||'',name:String(data.get('newname_'+i)||'').trim(),purchase:{reference:String(data.get('purchaseReference_'+i)||'').trim(),email:String(data.get('purchaseEmail_'+i)||'').trim()},segments:r.segments.map((s,j)=>Object.fromEntries(['origin','destination','departure','arrival','service','reference'].map(key=>[key,String(data.get(`${key}_${i}_${j}`)||'').trim()])))}))}
function drawRows(){const t=getState().trips.find(t=>t.id===reviewTripId);el('#associationRows').innerHTML=reviewRows.map((r,i)=>rowHTML(r,i,t)).join('')}
function review(path){const t=getTrip(),f=t.files.find(f=>f.path===path);if(!t||!f)return;let r=reading(t,path);if(!r){t.readings??={};r=t.readings[path]={name:f.name,fingerprint:fingerprint(f),text:'',status:'unread',proposals:[],warnings:["Este documento todavía no se ha leído. Puedes asociarlo manualmente o pulsar «Leer documentos»."]}}reviewPath=path;reviewTripId=t.id;if(r.reviewedFingerprint===r.fingerprint&&r.confirmed?.length){reviewRows=r.confirmed.map(c=>({enabled:true,personId:c.personId,name:t.people.find(p=>p.id===c.personId)?.name||'',purchase:structuredClone(c.purchase||r.purchase||{}),segments:structuredClone(c.segments||[])}))}else reviewRows=(r.proposals||[]).map(p=>({...structuredClone(p),enabled:!p.ambiguous&&!!p.personId}));if(!reviewRows.length)reviewRows=[{enabled:true,name:'',personId:'',purchase:r.purchase||extractPurchase(r.text||''),segments:[]}];modal("Revisar documento y pasajeros",`<p class="document-title">${esc(f.name)}</p><p class="muted small">Comprueba los nombres y trayectos. Las asociaciones se guardarán en las fichas sin cambiar los estados de billete o check-in.</p>${(r.warnings||[]).map(w=>`<div class="notice">${esc(w)}</div>`).join('')}<details class="source-text"><summary>Ver el texto leído ${r.method?'· '+esc(r.method):''}</summary><pre>${esc(r.text||"No hay texto disponible.")}</pre></details><div id="associationRows"></div><button type="button" class="button secondary" data-action="add-association">＋ Otra persona</button><div class="row-links"><button type="button" class="text-button" data-action="reread-document" data-id="${esc(path)}">Volver a leer el documento</button><button type="button" class="text-button" data-action="ignore-document" data-id="${esc(path)}">Omitir este documento</button></div>`,async()=>{collect();const current=getState().trips.find(x=>x.id===reviewTripId);const draft=applyReview(current,reviewPath,reviewRows);await ctx.saveTrip(draft);toast("Documento y trayectos asociados a los participantes.")},"Confirmar asociaciones");el('#modal').classList.add('document-modal');drawRows()}
function next(){const t=getTrip(),f=t.files.find(f=>{const r=reading(t,f.path);return r&&r.reviewedFingerprint!==r.fingerprint&&r.status!=='ignored'});if(f)review(f.path);else toast("No quedan propuestas por revisar.")}
function journeySummary(t,p){const journeys=journeysForPerson(t,p.id);return journeys.length?`<div class="participant-journeys">${journeys.map(s=>`<div class="person-journey"><strong>${esc(s.origin||"Origen pendiente")} → ${esc(s.destination||"Destino pendiente")}</strong><small>${esc(s.service||"Servicio pendiente")}${s.departure?' · '+esc(s.departure):''}</small>${s.arrival?`<small>Llegada: ${esc(s.arrival)}</small>`:''}${s.pending?"<small>Asociado automáticamente · pendiente de revisar</small>":''}${s.stale?"<small>Documento modificado · revisa la asociación</small>":''}</div>`).join('')}</div>`:''}
function arrivalSummary(t,p){if(p.arrival)return esc(p.arrival);const journeys=journeysForPerson(t,p.id);return journeys.length?journeys.map(s=>`<small>${esc(s.destination||"Destino pendiente")} · ${esc(s.arrival||"Hora pendiente")}</small>`).join(''):"Por confirmar"}
function originSummary(t,p){return esc(p.origin||journeysForPerson(t,p.id)[0]?.origin||"Origen pendiente")}
function personSummary(t,p){const records=recordsForPerson(t,p.id);return records.length?`<button type="button" class="text-button" data-action="person-documents" data-id="${p.id}">${records.length} documento${records.length===1?'':'s'} · Ver trayectos →</button>`:''}
function personDocuments(id){const t=getTrip(),p=t.people.find(p=>p.id===id);if(!p)return;const records=recordsForPerson(t,id);modal(`Documentos de ${p.name}`,records.length?records.map(r=>`<section class="panel"><h3>${esc(r.name)}</h3>${r.pending?"<p class=\"status\">Detectado automáticamente · pendiente de revisión</p>":''}${r.stale?"<p class=\"status\">El documento ha cambiado. Asociación anterior pendiente de revisión.</p>":''}${r.missing?"<p class=\"status\">Documento fuera de la carpeta actual</p>":''}${(r.purchases||[]).map(p=>`<dl class="detail-list purchase-details"><div><dt>Referencia de compra</dt><dd>${esc(p.reference||'No detectada')}</dd></div><div><dt>Email de compra</dt><dd>${esc(p.email||"No detectado")}</dd></div></dl>`).join('')}${r.segments.length?r.segments.map(s=>`<div class="person-journey"><strong>${esc(s.origin||"Origen por confirmar")} → ${esc(s.destination||"Destino por confirmar")}</strong><dl class="detail-list"><div><dt>Salida</dt><dd>${esc(s.departure||"Por confirmar")}</dd></div><div><dt>Llegada</dt><dd>${esc(s.arrival||"Por confirmar")}</dd></div><div><dt>Servicio</dt><dd>${esc(s.service||"Sin indicar")}</dd></div><div><dt>Localizador</dt><dd>${esc(s.reference||"Sin indicar")}</dd></div></dl></div>`).join(''):"<p class=\"muted\">Documento asociado sin trayectos detallados.</p>"}${!r.missing?`<div class="actions"><button type="button" class="button secondary" data-action="download-file" data-id="${t.files.findIndex(f=>f.path===r.path)}">Descargar documento</button><button type="button" class="button secondary" data-action="review-document" data-id="${esc(r.path)}">Revisar asociación</button></div>`:''}</section>`).join(''):"<p>No tiene documentos asociados.</p>",async()=>{},"Cerrar");el('#modal').classList.add('document-modal')}
function personCheckin(id){const t=getTrip(),p=t.people.find(p=>p.id===id);if(!p)return;modal(`Check-in · ${p.name}`,checkinHTML(t,p,esc)+select("Estado del check-in de todos los vuelos",'checkin',p.checkin||'Pendent',['Pendent','Fet','No cal']),async data=>{const draft=structuredClone(t);draft.people.find(x=>x.id===id).checkin=data.checkin;await ctx.saveTrip(draft);toast("Estado del check-in guardado.")},'Guardar estat');el('#modal').classList.add('document-modal')}
function personStatus(t,p){const records=recordsForPerson(t,p.id);return records.some(r=>r.pending)?"<span class=\"status\">Trayectos asociados · pendientes de revisar</span>":''}
function purchaseSummary(p){return (p.purchases||[]).map(b=>`<small class="purchase-summary">${b.reference?'Ref. '+esc(b.reference):"Referencia pendiente"}${b.email?'<br>'+esc(b.email):''}</small>`).join('')}
return {panel,status,journeySummary,arrivalSummary,originSummary,personSummary,personStatus,purchaseSummary,analyze,isBusy:()=>!!job,pending,handlers:{'person-checkin':personCheckin,'analyze-documents':()=>analyze(),'review-next':next,'stop-reading':()=>{job?.controller.abort();updateProgress("Deteniendo tras la página actual…")},'review-document':review,'person-documents':personDocuments,'reread-document':async path=>{el('#modal').close();await analyze(getTrip(),path);review(path)},'add-association':()=>{collect();reviewRows.push({enabled:true,name:'',personId:'',segments:[]});drawRows()},'remove-association':i=>{collect();reviewRows.splice(Number(i),1);drawRows()},'add-segment':i=>{collect();reviewRows[Number(i)].segments.push({});drawRows()},'remove-segment':key=>{collect();const[i,j]=key.split(':').map(Number);reviewRows[i].segments.splice(j,1);drawRows()},'ignore-document':async path=>{const t=getTrip(),r=reading(t,path);if(r?.confirmed?.length&&!confirm("Este documento ya tiene asociaciones. ¿Quieres quitarlas y omitirlo?"))return;if(r){const draft=structuredClone(t);draft.readings[path].status='ignored';draft.readings[path].confirmed=[];draft.readings[path].reviewedFingerprint=null;for(const p of draft.people)p.purchases=(p.purchases||[]).filter(b=>b.documentPath!==path);syncJourneys(draft);await ctx.saveTrip(draft)}el('#modal').close()}}}
}
